package com.tarapickle.identity.application;
import com.tarapickle.identity.api.IdentityDtos.*; import com.tarapickle.identity.domain.model.*; import com.tarapickle.identity.domain.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class AccountService {private final UserRepository users;private final CredentialRepository credentials;private final SessionRepository sessions;private final UserRoleRepository roles;private final SecurityEventRepository events;private final PasswordEncoder encoder;private final Clock clock;
 @Transactional(readOnly=true) public AccountResponse me(UUID uid){User u=user(uid);return new AccountResponse(u.getId(),u.getEmail(),u.getEmailVerifiedAt()!=null,u.getGivenName(),u.getFamilyName(),u.getStatus().name(),roles.roles(uid),u.getCreatedAt());}
 @Transactional public AccountResponse update(UUID uid,UpdateAccountRequest r){User u=user(uid);u.updateName(r.givenName(),r.familyName(),clock.instant());return new AccountResponse(u.getId(),u.getEmail(),u.getEmailVerifiedAt()!=null,u.getGivenName(),u.getFamilyName(),u.getStatus().name(),roles.roles(uid),u.getCreatedAt());}
 @Transactional(readOnly=true) public List<SessionResponse> list(UUID uid,UUID current){return sessions.findAllByUserIdOrderByCreatedAtDesc(uid).stream().map(s->new SessionResponse(s.getId(),s.getCreatedAt(),s.getLastUsedAt(),s.getExpiresAt(),s.getId().equals(current),s.getRevokedAt()!=null,s.getUserAgent())).toList();}
 @Transactional public void logout(UUID uid,UUID sid){UserSession s=owned(uid,sid);s.revoke(clock.instant());events.save(new SecurityEvent(uid,sid,"SESSION_REVOKED","SUCCESS",clock.instant(),null));}
 @Transactional public void revoke(UUID uid,UUID sid){logout(uid,sid);}
 @Transactional public void revokeAll(UUID uid){Instant now=clock.instant();sessions.findAllByUserIdOrderByCreatedAtDesc(uid).forEach(s->s.revoke(now));events.save(new SecurityEvent(uid,null,"ALL_SESSIONS_REVOKED","SUCCESS",now,null));}
 @Transactional public void change(UUID uid,UUID current,ChangePasswordRequest r){UserCredential c=credentials.findById(uid).orElseThrow();if(!encoder.matches(r.currentPassword(),c.getPasswordHash()))throw IdentityException.badCredentials();if(r.newPassword().length()<12||!r.newPassword().matches(".*[A-Z].*")||!r.newPassword().matches(".*[a-z].*")||!r.newPassword().matches(".*[0-9].*"))throw new IdentityException(HttpStatus.UNPROCESSABLE_ENTITY,"WEAK_PASSWORD","New password does not meet policy.");Instant now=clock.instant();c.changePassword(encoder.encode(r.newPassword()),now);sessions.findAllByUserIdOrderByCreatedAtDesc(uid).stream().filter(s->!s.getId().equals(current)).forEach(s->s.revoke(now));events.save(new SecurityEvent(uid,current,"PASSWORD_CHANGED","SUCCESS",now,null));}
 private User user(UUID id){return users.findById(id).orElseThrow(()->new IdentityException(HttpStatus.NOT_FOUND,"ACCOUNT_NOT_FOUND","Account not found."));} private UserSession owned(UUID uid,UUID sid){return sessions.findById(sid).filter(s->s.getUserId().equals(uid)).orElseThrow(()->new IdentityException(HttpStatus.NOT_FOUND,"SESSION_NOT_FOUND","Session not found."));}
}
